window.VO = [{"id":"n01","text":"You just left your wallet next to a pickpocket.","at":0,"t0":0,"t1":2.375},{"id":"n02","text":"And there's cash in it.","at":5.25,"t0":2.625,"t1":3.805},{"id":"n03","text":"Would anyone give that back?","at":8.21,"t0":4.105,"t1":5.655},{"id":"n04","text":"Which wallets do strangers try to return more often?","at":12.11,"t0":6.055,"t1":8.78},{"id":"n05","text":"With cash, or empty?","at":18.06,"t0":9.03,"t1":10.36},{"id":"n06","text":"Scientists once handed in seventeen thousand \"lost\" wallets, at hotels, banks and police stations.","at":23.12,"t0":11.56,"t1":17.67},{"id":"n07","text":"With no cash, four in ten got in touch with the owner.","at":36.04,"t0":18.02,"t1":21.005},{"id":"n08","text":"With cash, half did.","at":43.21,"t0":21.605,"t1":22.965},{"id":"n09","text":"Most people they asked said empty.","at":46.83,"t0":23.415,"t1":25.285},{"id":"n10f","text":"Why? Because keeping someone's cash feels more like stealing, and almost nobody wants to see themselves as a thief.","at":51.47,"t0":25.735,"t1":32.4},{"id":"n13","text":"He already is one.","at":67.1,"t0":33.55,"t1":34.785},{"id":"n14","text":"And nobody would ever know.","at":72.91,"t0":36.455,"t1":37.93},{"id":"n15","text":"You come back.","at":83.26,"t0":41.63,"t1":42.535},{"id":"n16","text":"Because to him, picking pockets is work.","at":92.47,"t0":46.235,"t1":48.56},{"id":"n17","text":"But keeping what you lost?","at":97.92,"t0":48.96,"t1":50.335},{"id":"n18","text":"That's stealing.","at":101.37,"t0":50.685,"t1":51.705},{"id":"n19","text":"It's all there.","at":105.51,"t0":52.755,"t1":53.585},{"id":"n20b","text":"Plus a chai.","at":107.77,"t0":53.885,"t1":54.87}];
